fn element_wise_modulo(a: Vec<i32>, b: Vec<i32>) -> Vec<i32> {
    // Since both vectors have the same length and b contains no zeros,
    // we can safely zip and compute the remainder for each pair.
    a.into_iter()
     .zip(b.into_iter())
     .map(|(x, y)| x % y)
     .collect()
}

